public class StreamJoinTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("initials basic", "A.G.L", StreamJoin.initials(java.util.List.of("Ada", "grace", "linus")));
        check("initials single name", "B", StreamJoin.initials(java.util.List.of("bob")));
        check("initials skips blanks", "C", StreamJoin.initials(java.util.List.of("", "   ", "carol")));
        check("initials empty list", "", StreamJoin.initials(java.util.List.of()));
        check("distinct ignoring case", 4L, StreamJoin.countDistinctWords("the cat and THE dog"));
        check("extra whitespace", 2L, StreamJoin.countDistinctWords("  hello   world hello "));
        check("blank sentence", 0L, StreamJoin.countDistinctWords("   "));
        check("one word repeated", 1L, StreamJoin.countDistinctWords("Echo echo ECHO"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
