public class StreamJoin {

    public static String initials(java.util.List<String> names) {
        return names.stream()
                .filter(name -> !name.isBlank())
                .map(name -> String.valueOf(Character.toUpperCase(name.trim().charAt(0))))
                .collect(java.util.stream.Collectors.joining("."));
    }

    public static long countDistinctWords(String sentence) {
        return java.util.Arrays.stream(sentence.trim().split("\\s+"))
                .filter(word -> !word.isEmpty())
                .map(String::toLowerCase)
                .distinct()
                .count();
    }
}
